import React, { useState } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");

  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://localhost:8000/upload-statement/", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();
      setTransactions(data.transactions);
      setType(data.detected_type);
    } catch (err) {
      console.error(err);
      alert("Upload failed");
    }
  };

  return (
    <div className="app">

      {/* TOP BAR */}
      <header className="topbar">
        <div className="brand">FinSight</div>

        <nav className="nav">
          <span>Overview</span>
          <span>Transactions</span>
          <span>Insights</span>
        </nav>
      </header>

      {/* HERO */}
      <section className="hero">
        <h1>Understand your money, instantly.</h1>
        <p>AI-powered statement analysis for smarter financial decisions.</p>
      </section>

      {/* KPI STRIP */}
      <section className="kpis">
        <div className="kpi">
          <div className="label">Source</div>
          <div className="value">{type || "—"}</div>
        </div>

        <div className="kpi">
          <div className="label">Transactions</div>
          <div className="value">{transactions.length}</div>
        </div>

        <div className="kpi">
          <div className="label">Status</div>
          <div className={`value ${transactions.length ? "good" : "muted"}`}>
            {transactions.length ? "Processed" : "Waiting"}
          </div>
        </div>
      </section>

      {/* GRID */}
      <section className="grid">

        {/* UPLOAD */}
        <div className="panel">
          <h3>Upload statement</h3>
          <p className="subtext">Drag & drop or select a PDF file.</p>

          <input
            type="file"
            accept=".pdf"
            onChange={(e) => setFile(e.target.files[0])}
          />

          <button onClick={handleUpload}>
            Analyze statement
          </button>
        </div>

        {/* SUMMARY */}
        <div className="panel">
          <h3>Overview</h3>
          <p className="subtext">
            We automatically extract transactions, categorize spend, and detect patterns.
          </p>
        </div>
      </section>

      {/* TABLE */}
      {transactions.length > 0 && (
        <section className="table-card">
          <h3>Transactions</h3>

          <table>
            <thead>
              <tr>
                <th>Date</th>
                <th>Type</th>
                <th>Description</th>
                <th className="right">Amount</th>
              </tr>
            </thead>

            <tbody>
              {transactions.map((txn, i) => (
                <tr key={i}>
                  <td>{txn.date}</td>
                  <td className={txn.type}>{txn.type}</td>
                  <td>{txn.description}</td>
                  <td className="right">₹{txn.amount}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      )}

    </div>
  );
}

export default Dashboard;
